settings.cellContentFunction:
return value === true || value === "true"
    ? "🟢 Online"
    : "🔴 Offline";

if (value === null || value === undefined || value === "") {
    return "Never connected";
}

const timestamp = Number(value);

if (!Number.isFinite(timestamp)) {
    return "Invalid timestamp";
}

return new Date(timestamp).toLocaleString("en-GB", {
    timeZone: "Asia/Kathmandu",
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
});

settings.css:
.water-header {
  height: 100%;
  min-height: 0;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 14px 24px;
  border-radius: 10px;
  position: relative;
  overflow: hidden;
  color: #fff;
  background: linear-gradient(110deg, #0d2538, #163850 65%, #0f4c5c);
  font-family: Inter, Roboto, Arial, sans-serif;
}

.water-header-icon {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  padding: 10px;
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 10px;
  color: #a5dce7;
  box-sizing: border-box;
}

.water-header-icon svg {
  width: 100%;
  height: 100%;
}

.water-header-content {
  position: relative;
  z-index: 2;
  min-width: 0;
}

.water-header-content h1 {
  margin: 0;
  font-size: clamp(17px, 2vw, 25px);
  font-weight: 650;
  line-height: 1.25;
  letter-spacing: -.5px;
  color: white;
}

.water-header-content p {
  margin: 8px 0 0;
  font-size: 12px;
  color: #cbd5e1;
}

.water-header-content p span {
  padding: 0 7px;
  color: #7dd3fc;
}

.water-header-decoration {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 38%;
  max-width: 310px;
  color: white;
  pointer-events: none;
}

.water-header-decoration svg {
  width: 100%;
  display: block;
}

@media (max-width: 650px) {
  .water-header {
    padding: 14px 16px;
    gap: 12px;
  }

  .water-header-content h1 {
    font-size: 16px;
  }

  .water-header-decoration {
    opacity: .35;
  }
}
